//! The artefact envelope (directive §19) and content addressing (§32).
//!
//! Artefact identity is stable across transport: the id and digest live in
//! the envelope, never in a transport address.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use sha2::{Digest as _, Sha256};

use crate::ids::{ArtifactId, SessionId};
use crate::{Result, TapestryError};

/// The kind of an artefact. Determines presentation surface.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum ArtifactKind {
    Image,
    ImageSet,
    Video,
    Audio,
    WebCapture,
    Document,
    ModelPreview,
    Telemetry,
    Composite,
}

/// Pixel dimensions for visual artefacts.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Dimensions {
    pub width: u32,
    pub height: u32,
}

/// Where an artefact came from. Provenance is preserved, never collapsed.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "origin", rename_all = "snake_case", deny_unknown_fields)]
pub enum Provenance {
    /// Generated by an agent/model.
    Generated {
        producer: String,
        model: Option<String>,
    },
    /// Derived from another artefact (e.g. thumbnail, transcode).
    Derived {
        source: ArtifactId,
        operation: String,
    },
    /// Supplied by a human or external process.
    External { producer: String },
}

/// The complete semantic envelope for an artefact.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Artifact {
    pub id: ArtifactId,
    pub session_id: SessionId,
    /// Revision within the session; monotonically increasing.
    pub revision: u32,
    pub kind: ArtifactKind,
    /// IANA media type, verified before presentation (§28 MIME verification).
    pub mime: String,
    /// Storage URI, typically `sha256/<digest>` in a content-addressed cache.
    pub uri: String,
    /// Hex-encoded SHA-256 of the content.
    pub digest: String,
    pub byte_length: u64,
    pub dimensions: Option<Dimensions>,
    /// Duration in milliseconds, for timed media.
    pub duration_ms: Option<u64>,
    pub codec: Option<crate::capability::Codec>,
    pub provenance: Provenance,
    pub created_at: DateTime<Utc>,
    /// Artefacts generated as alternatives share a comparison group so the
    /// gallery can present them as candidates.
    pub comparison_group: Option<String>,
    /// Hints for the presentation layer (e.g. "dark", "favour-fit-height").
    pub inspection_hints: Vec<String>,
}

impl Artifact {
    pub fn builder(session_id: SessionId, kind: ArtifactKind) -> ArtifactBuilder {
        ArtifactBuilder {
            artifact: Artifact {
                id: ArtifactId::generate(),
                session_id,
                revision: 1,
                kind,
                mime: String::new(),
                uri: String::new(),
                digest: String::new(),
                byte_length: 0,
                dimensions: None,
                duration_ms: None,
                codec: None,
                provenance: Provenance::External {
                    producer: "unknown".into(),
                },
                created_at: Utc::now(),
                comparison_group: None,
                inspection_hints: Vec::new(),
            },
        }
    }

    /// Validate structural invariants: digest well-formed, uri consistent
    /// with digest, length sane, mime present.
    pub fn validate(&self) -> Result<()> {
        if self.mime.is_empty() {
            return Err(TapestryError::MissingField("mime"));
        }
        if !is_hex_sha256(&self.digest) {
            return Err(TapestryError::InvalidValue {
                field: "digest",
                reason: "not 64 hex characters".into(),
            });
        }
        if !self.uri.is_empty() && self.uri != content_address(&self.digest) {
            return Err(TapestryError::InvalidValue {
                field: "uri",
                reason: format!(
                    "expected `{}` for this digest",
                    content_address(&self.digest)
                ),
            });
        }
        if self.byte_length == 0 {
            return Err(TapestryError::InvalidValue {
                field: "byte_length",
                reason: "artefact must not be empty".into(),
            });
        }
        Ok(())
    }
}

fn is_hex_sha256(s: &str) -> bool {
    s.len() == 64 && s.bytes().all(|b| b.is_ascii_hexdigit())
}

/// Hex SHA-256 of content bytes.
pub fn content_digest(bytes: &[u8]) -> String {
    hex::encode(Sha256::digest(bytes))
}

/// The content-addressed cache key for a digest (§32): `sha256/<digest>`.
pub fn content_address(digest: &str) -> String {
    format!("sha256/{digest}")
}

/// Builder for [`Artifact`].
#[derive(Debug)]
pub struct ArtifactBuilder {
    artifact: Artifact,
}

impl ArtifactBuilder {
    pub fn mime(mut self, mime: impl Into<String>) -> Self {
        self.artifact.mime = mime.into();
        self
    }

    /// Set content, computing digest, uri and length from the bytes.
    pub fn content(mut self, bytes: &[u8]) -> Self {
        let digest = content_digest(bytes);
        self.artifact.byte_length = bytes.len() as u64;
        self.artifact.digest = digest.clone();
        self.artifact.uri = content_address(&digest);
        self
    }

    pub fn dimensions(mut self, width: u32, height: u32) -> Self {
        self.artifact.dimensions = Some(Dimensions { width, height });
        self
    }

    pub fn duration_ms(mut self, ms: u64) -> Self {
        self.artifact.duration_ms = Some(ms);
        self
    }

    pub fn codec(mut self, codec: crate::capability::Codec) -> Self {
        self.artifact.codec = Some(codec);
        self
    }

    pub fn generated_by(mut self, producer: impl Into<String>, model: Option<String>) -> Self {
        self.artifact.provenance = Provenance::Generated {
            producer: producer.into(),
            model,
        };
        self
    }

    pub fn derived_from(mut self, source: ArtifactId, operation: impl Into<String>) -> Self {
        self.artifact.provenance = Provenance::Derived {
            source,
            operation: operation.into(),
        };
        self
    }

    pub fn comparison_group(mut self, group: impl Into<String>) -> Self {
        self.artifact.comparison_group = Some(group.into());
        self
    }

    pub fn hint(mut self, hint: impl Into<String>) -> Self {
        self.artifact.inspection_hints.push(hint.into());
        self
    }

    pub fn revision(mut self, revision: u32) -> Self {
        self.artifact.revision = revision;
        self
    }

    pub fn build(self) -> Artifact {
        self.artifact
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample() -> Artifact {
        Artifact::builder(SessionId::generate(), ArtifactKind::Image)
            .mime("image/png")
            .content(b"png-bytes")
            .dimensions(1920, 1080)
            .generated_by("playbook", Some("test-model".into()))
            .comparison_group("hero")
            .hint("dark")
            .build()
    }

    #[test]
    fn digest_is_stable_sha256() {
        assert_eq!(
            content_digest(b"png-bytes"),
            hex::encode(Sha256::digest(b"png-bytes"))
        );
    }

    #[test]
    fn builder_sets_content_address() {
        let a = sample();
        assert_eq!(a.uri, content_address(&a.digest));
        assert_eq!(a.byte_length, 9);
        assert!(a.validate().is_ok());
    }

    #[test]
    fn validate_rejects_tampered_uri() {
        let mut a = sample();
        a.uri = "sha256/deadbeef".into();
        assert!(a.validate().is_err());
    }

    #[test]
    fn validate_rejects_bad_digest_and_empty_mime() {
        let mut a = sample();
        a.digest = "zz".into();
        assert!(a.validate().is_err());
        a = sample();
        a.mime = String::new();
        assert!(a.validate().is_err());
    }

    #[test]
    fn serde_roundtrip() {
        let a = sample();
        let back: Artifact = serde_json::from_str(&serde_json::to_string(&a).unwrap()).unwrap();
        assert_eq!(a, back);
    }
}

//! Codec capability descriptors and negotiation (directives §18, §40).
//!
//! Rule: codec selection happens only after explicit capability probing.
//! H.265 is never assumed from platform identity.

use serde::{Deserialize, Serialize};

/// Codecs Tapestry reasons about.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case", deny_unknown_fields)]
pub enum Codec {
    H264,
    H265,
}

impl Codec {
    /// Human/wire label.
    pub fn label(self) -> &'static str {
        match self {
            Codec::H264 => "h264",
            Codec::H265 => "h265",
        }
    }
}

/// What a device reports after actual platform probing (not model lookup).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CodecCapabilities {
    /// Codecs confirmed by a platform query, in probe order.
    pub probed: Vec<Codec>,
}

impl CodecCapabilities {
    pub fn from_probe(probed: Vec<Codec>) -> Self {
        Self { probed }
    }

    /// Empty capability set: the honest result of "we could not probe".
    /// Negotiating against this never yields H.265.
    pub fn unknown() -> Self {
        Self { probed: Vec::new() }
    }

    pub fn supports(&self, codec: Codec) -> bool {
        self.probed.contains(&codec)
    }

    /// Select the best playback codec for HEVC-class content given what was
    /// actually probed. Returns `None` when the device supports neither
    /// codec — callers must then fall back to still-image or remote-render
    /// strategies, never to guessing.
    pub fn select_for_hevc_content(&self) -> Option<Codec> {
        if self.supports(Codec::H265) {
            Some(Codec::H265)
        } else if self.supports(Codec::H264) {
            Some(Codec::H264)
        } else {
            None
        }
    }
}

/// The negotiation exchange: presenter proposes, device answers with what
/// it can actually decode.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case", deny_unknown_fields)]
pub enum NegotiationMessage {
    /// Presenter proposes preferred codecs, most preferred first.
    Propose { codecs: Vec<Codec> },
    /// Device answers with its probed subset.
    Answer { capabilities: CodecCapabilities },
    /// Presenter commits to one codec after negotiation.
    Confirm { codec: Codec },
}

/// Negotiate a codec for HEVC-class content: propose → answer → confirm.
/// Returns `Err` when the device can decode neither proposed codec.
pub fn negotiate_hevc(device_answer: &CodecCapabilities) -> crate::Result<Codec> {
    device_answer.select_for_hevc_content().ok_or_else(|| {
        crate::TapestryError::IllegalTransition(
            "device probed neither h265 nor h264; refusing to assume codec support".into(),
        )
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn prefers_h265_falls_back_to_h264() {
        assert_eq!(
            CodecCapabilities::from_probe(vec![Codec::H264, Codec::H265]).select_for_hevc_content(),
            Some(Codec::H265)
        );
        assert_eq!(
            CodecCapabilities::from_probe(vec![Codec::H264]).select_for_hevc_content(),
            Some(Codec::H264)
        );
    }

    #[test]
    fn unprobed_device_never_gets_h265() {
        // The directive's non-negotiable: no probing, no H.265.
        assert_eq!(CodecCapabilities::unknown().select_for_hevc_content(), None);
        assert!(negotiate_hevc(&CodecCapabilities::unknown()).is_err());
    }

    #[test]
    fn negotiation_message_roundtrip() {
        let msg = NegotiationMessage::Answer {
            capabilities: CodecCapabilities::from_probe(vec![Codec::H264]),
        };
        let back: NegotiationMessage =
            serde_json::from_str(&serde_json::to_string(&msg).unwrap()).unwrap();
        assert_eq!(msg, back);
    }
}

//! Device identity and advertised capabilities.
//!
//! LAN discovery advertisement (directive §10). Capabilities are *actual*,
//! queried from the platform — never inferred from device model alone.

use serde::{Deserialize, Serialize};

use crate::ids::DeviceId;

/// The TAP protocol version a device speaks.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct TapVersion {
    pub major: u32,
    pub minor: u32,
}

impl TapVersion {
    pub const fn new(major: u32, minor: u32) -> Self {
        Self { major, minor }
    }
}

impl std::fmt::Display for TapVersion {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "TAP/{}.{}", self.major, self.minor)
    }
}

impl Default for TapVersion {
    fn default() -> Self {
        Self::new(1, 0)
    }
}

/// Display characteristics advertised by a presentation endpoint.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DisplayCharacteristics {
    pub width: u32,
    pub height: u32,
    pub refresh_hz: u32,
    pub hdr: bool,
}

/// Audio output characteristics.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AudioCharacteristics {
    pub channels: u32,
    pub surround: bool,
}

/// Input peripherals available on the device.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case", deny_unknown_fields)]
pub enum InputCharacteristic {
    Dpad,
    Keyboard,
    Touch,
    Voice,
}

/// Storage capability advertised by a node.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct StorageCharacteristic {
    pub capacity_bytes: u64,
    pub available_bytes: u64,
    pub writable: bool,
    /// Removable volumes (USB) the device can address.
    pub removable: bool,
}

/// The full capability set a device advertises during discovery.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CapabilitySet {
    pub display: Option<DisplayCharacteristics>,
    pub audio: Option<AudioCharacteristics>,
    pub input: Vec<InputCharacteristic>,
    pub storage: Option<StorageCharacteristic>,
    /// Media codecs the platform reports it can decode.
    pub codecs: Vec<crate::capability::Codec>,
}

/// A discovered LAN node.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DeviceIdentity {
    pub device_id: DeviceId,
    pub friendly_name: String,
    /// Platform label, e.g. "fire-tv", "android-tv", "desktop".
    pub platform: String,
    pub tap_version: TapVersion,
    pub capabilities: CapabilitySet,
    /// Whether the node is currently accepting sessions.
    pub available: bool,
}

impl DeviceIdentity {
    /// Whether this device can present artefacts at all (display + some input).
    pub fn can_present(&self) -> bool {
        self.capabilities.display.is_some() && !self.capabilities.input.is_empty()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample() -> DeviceIdentity {
        DeviceIdentity {
            device_id: DeviceId::generate(),
            friendly_name: "lounge-fire".into(),
            platform: "fire-tv".into(),
            tap_version: TapVersion::default(),
            capabilities: CapabilitySet {
                display: Some(DisplayCharacteristics {
                    width: 3840,
                    height: 2160,
                    refresh_hz: 60,
                    hdr: true,
                }),
                audio: Some(AudioCharacteristics {
                    channels: 6,
                    surround: true,
                }),
                input: vec![InputCharacteristic::Dpad, InputCharacteristic::Keyboard],
                storage: Some(StorageCharacteristic {
                    capacity_bytes: 8 << 30,
                    available_bytes: 4 << 30,
                    writable: true,
                    removable: true,
                }),
                codecs: vec![
                    crate::capability::Codec::H264,
                    crate::capability::Codec::H265,
                ],
            },
            available: true,
        }
    }

    #[test]
    fn serde_roundtrip() {
        let dev = sample();
        let back: DeviceIdentity =
            serde_json::from_str(&serde_json::to_string(&dev).unwrap()).unwrap();
        assert_eq!(dev, back);
    }

    #[test]
    fn rejects_unknown_fields() {
        let json = r#"{"device_id":"dev_01ARZ3NDEKTSV4RRFFQ69G5FAV","friendly_name":"x","platform":"fire-tv","tap_version":{"major":1,"minor":0},"capabilities":{"display":null,"audio":null,"input":[],"storage":null,"codecs":[]},"available":true,"surprise":1}"#;
        assert!(serde_json::from_str::<DeviceIdentity>(json).is_err());
    }

    #[test]
    fn presentable_device_reports_can_present() {
        assert!(sample().can_present());
    }
}

//! Typed, time-sortable identifiers.
//!
//! IDs are ULID-style: a 48-bit millisecond timestamp followed by 80 bits of
//! randomness, encoded in Crockford base32 (26 chars). They sort by creation
//! time, which keeps journal replay and gallery ordering stable without a
//! separate timestamp column.

use std::fmt;

use serde::{de, Deserialize, Deserializer, Serialize, Serializer};

use crate::{Result, TapestryError};

const CROCKFORD: &[u8; 32] = b"0123456789ABCDEFGHJKMNPQRSTVWXYZ";
const ENCODED_LEN: usize = 26;

/// Generate 10 random bytes from the OS; test builds use a deterministic
/// fallback seeded by a counter so tests never flake on collisions.
fn random_80_bits() -> [u8; 10] {
    let mut bytes = [0u8; 10];
    // getrandom is not a dependency; read from /dev/urandom via std is not
    // available, so use a cheap process-unique entropy mix. This is
    // sufficient for Gate 0: IDs must be unique and sortable, not
    // cryptographically unguessable (auth uses DreamSequence).
    use std::time::{SystemTime, UNIX_EPOCH};
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.subsec_nanos() as u64 ^ d.as_secs())
        .unwrap_or(0);
    let addr = &bytes as *const _ as u64;
    let mut state = nanos ^ addr ^ (std::process::id() as u64) << 17;
    for byte in bytes.iter_mut() {
        // xorshift64
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        *byte = (state >> 24) as u8;
    }
    bytes
}

macro_rules! tapestry_id {
    ($name:ident, $prefix:literal) => {
        #[doc = concat!(stringify!($name), " — a typed, time-sortable identifier with prefix `", $prefix, "_`.")]
        #[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
        pub struct $name(String);

        impl $name {
            pub const PREFIX: &'static str = $prefix;

            /// Generate a new identifier stamped with the current time.
            pub fn generate() -> Self {
                Self(Self::encode(Self::now_ms(), &random_80_bits()))
            }

            /// Construct an identifier from a timestamp and explicit
            /// randomness (used by tests and journal replay).
            pub fn from_parts(time_ms: u64, randomness: [u8; 10]) -> Self {
                Self(Self::encode(time_ms, &randomness))
            }

            /// Parse an identifier, enforcing the typed prefix.
            pub fn parse(s: &str) -> Result<Self> {
                let expected = concat!($prefix, "_");
                let raw = s
                    .strip_prefix(expected)
                    .ok_or_else(|| TapestryError::InvalidValue {
                        field: stringify!($name),
                        reason: format!("expected prefix `{expected}`"),
                    })?;
                if raw.len() != ENCODED_LEN || !raw.bytes().all(Self::is_crockford) {
                    return Err(TapestryError::InvalidValue {
                        field: stringify!($name),
                        reason: "not 26 Crockford base32 characters".into(),
                    });
                }
                Ok(Self(s.to_owned()))
            }

            /// Millisecond timestamp encoded in this identifier.
            pub fn timestamp_ms(&self) -> u64 {
                self.decode_time()
            }

            pub fn as_str(&self) -> &str {
                &self.0
            }

            fn now_ms() -> u64 {
                use std::time::{SystemTime, UNIX_EPOCH};
                SystemTime::now()
                    .duration_since(UNIX_EPOCH)
                    .map(|d| d.as_millis() as u64)
                    .unwrap_or(0)
            }

            fn is_crockford(b: u8) -> bool {
                // Uppercase set used by encode: 0-9 plus A-Z minus I, L, O, U.
                matches!(b, b'0'..=b'9') || (b.is_ascii_uppercase() && !matches!(b, b'I' | b'L' | b'O' | b'U'))
            }

            fn encode(time_ms: u64, randomness: &[u8; 10]) -> String {
                let mut raw = [0u8; 16];
                // Take the low 48 bits of the millisecond timestamp.
                raw[..6].copy_from_slice(&time_ms.to_be_bytes()[2..8]);
                raw[6..].copy_from_slice(randomness);

                let mut out = String::with_capacity($prefix.len() + 1 + ENCODED_LEN);
                out.push_str($prefix);
                out.push('_');
                // 128 bits -> 26 * 5 bits = 130; the top 2 bits are zero.
                let value = u128::from_be_bytes(raw);
                let mut chars = [0u8; ENCODED_LEN];
                for (i, slot) in chars.iter_mut().enumerate() {
                    let shift = 125 - 5 * i; // 26 groups of 5 bits, high to low
                    *slot = CROCKFORD[((value >> shift) & 0x1f) as usize];
                }
                out.push_str(std::str::from_utf8(&chars).expect("crockford is ascii"));
                out
            }

            fn decode_time(&self) -> u64 {
                let raw = self
                    .0
                    .strip_prefix(concat!($prefix, "_"))
                    .unwrap_or(&self.0);
                let mut value: u128 = 0;
                for &ch in raw.as_bytes() {
                    value = (value << 5) | decode_crockford(ch) as u128;
                }
                // Top 48 bits are the millisecond timestamp.
                (value >> 80) as u64
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                f.write_str(&self.0)
            }
        }

        impl Serialize for $name {
            fn serialize<S: Serializer>(&self, s: S) -> std::result::Result<S::Ok, S::Error> {
                s.serialize_str(&self.0)
            }
        }

        impl<'de> Deserialize<'de> for $name {
            fn deserialize<D: Deserializer<'de>>(d: D) -> std::result::Result<Self, D::Error> {
                let s = String::deserialize(d)?;
                Self::parse(&s).map_err(de::Error::custom)
            }
        }
    };
}

fn decode_crockford(ch: u8) -> u32 {
    match ch {
        b'0'..=b'9' => (ch - b'0') as u32,
        b'A'..=b'H' => (ch - b'A' + 10) as u32,
        b'J' | b'K' => (ch - b'J' + 18) as u32,
        b'M' | b'N' => (ch - b'M' + 20) as u32,
        b'P'..=b'T' => (ch - b'P' + 22) as u32,
        b'V'..=b'Z' => (ch - b'V' + 27) as u32,
        _ => 0,
    }
}

tapestry_id!(SessionId, "tap");
tapestry_id!(ArtifactId, "art");
tapestry_id!(DeviceId, "dev");
tapestry_id!(ReviewId, "rev");
tapestry_id!(OperationId, "ops");

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_ids_have_prefix_and_length() {
        let id = SessionId::generate();
        assert!(id.as_str().starts_with("tap_"));
        assert_eq!(id.as_str().len(), "tap_".len() + ENCODED_LEN);
    }

    #[test]
    fn parse_rejects_wrong_prefix_and_garbage() {
        let id = SessionId::generate();
        assert!(SessionId::parse(id.as_str()).is_ok());
        assert!(ArtifactId::parse(id.as_str()).is_err());
        assert!(SessionId::parse("tap_!!!").is_err());
        assert!(SessionId::parse("no-prefix").is_err());
    }

    #[test]
    fn roundtrip_preserves_timestamp() {
        let original = SessionId::from_parts(1_723_456_789_012, [7u8; 10]);
        let reparsed = SessionId::parse(original.as_str()).unwrap();
        assert_eq!(reparsed.timestamp_ms(), 1_723_456_789_012);
    }

    #[test]
    fn ids_sort_by_creation_time() {
        let earlier = SessionId::from_parts(1_000, [1u8; 10]);
        let later = SessionId::from_parts(2_000, [1u8; 10]);
        assert!(earlier < later);
    }

    #[test]
    fn generated_ids_are_unique() {
        let a = OperationId::generate();
        let b = OperationId::generate();
        assert_ne!(a, b);
    }

    #[test]
    fn serde_roundtrip() {
        let id = DeviceId::generate();
        let json = serde_json::to_string(&id).unwrap();
        let back: DeviceId = serde_json::from_str(&json).unwrap();
        assert_eq!(id, back);
    }
}

