        assert!(f.validate().is_err());
    }

    #[test]
    fn oversized_frame_rejected() {
        let mut f = sample(vec![0u8; 64]);
        f.len = MAX_FRAME_PAYLOAD + 1;
        assert!(f.validate().is_err());
    }

    #[test]
    fn chunk_size_limit_enforced() {
        let mut f = sample(vec![0u8; 8]);
        f.frame_type = "chunk".into();
        f.offset = Some(0);
