        let mut s = Session::new("hello");
        let event = s.transition_to(SessionState::Planning, Utc::now()).unwrap();
        assert!(!s.apply(&event).unwrap()); // duplicate seq
        let mut replay = event.clone();
        replay.seq += 5;
        assert!(s.apply(&replay).is_err()); // gap
    }

