    }
}

//! Telemetry correlation hierarchy and timing-event names (directive §30).
//!
//! Only names and correlation ids live here. Emission, sampling and export
//! belong to the observability swarm.

use serde::{Deserialize, Serialize};

use crate::ids::{OperationId, SessionId};

/// Correlation hierarchy: programme > session > drive > task > operation.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Correlation {
    pub programme: String,
    pub session: SessionId,
    /// Playbook drive identifier, when the session is playbook-governed.
    pub drive: Option<String>,
    pub task: Option<String>,
    pub operation: OperationId,
    /// artefact / transfer / review correlation, when applicable.
    pub artifact: Option<crate::ids::ArtifactId>,
}

/// The timed spans every task SHALL emit, in causal order.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum TimingEvent {
    PromptAdmission,
    PlaybookDecision,
    ProviderQueue,
    Inference,
    MesutQueue,
    MesutDispatch,
    LocalExecution,
    Transfer,
    Decode,
    FirstFrame,
    HumanReview,
    ReturnCallback,
}

impl TimingEvent {
    /// All events, in expected causal order (for schema validation of traces).
    pub const ALL: &'static [TimingEvent] = &[
        TimingEvent::PromptAdmission,
        TimingEvent::PlaybookDecision,
        TimingEvent::ProviderQueue,
        TimingEvent::Inference,
        TimingEvent::MesutQueue,
        TimingEvent::MesutDispatch,
        TimingEvent::LocalExecution,
        TimingEvent::Transfer,
        TimingEvent::Decode,
        TimingEvent::FirstFrame,
        TimingEvent::HumanReview,
        TimingEvent::ReturnCallback,
    ];
}

/// One measured span.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Timing {
    pub event: TimingEvent,
    /// Milliseconds since correlation start.
    pub elapsed_ms: u64,
    pub duration_ms: u64,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn correlation_roundtrip() {
        let c = Correlation {
            programme: "tapestry".into(),
            session: SessionId::generate(),
            drive: Some("drive-1".into()),
            task: Some("task-1".into()),
            operation: OperationId::generate(),
            artifact: None,
        };
        let back: Correlation = serde_json::from_str(&serde_json::to_string(&c).unwrap()).unwrap();
        assert_eq!(c, back);
    }

    #[test]
    fn timing_events_roundtrip_by_name() {
        for event in TimingEvent::ALL {
            let json = serde_json::to_string(event).unwrap();
            let back: TimingEvent = serde_json::from_str(&json).unwrap();
            assert_eq!(event, &back);
        }
    }
}

//! Codec negotiation: H.265 only after explicit probing, H.264 fallback,
//! honest refusal when nothing was probed.

use tapestry_core::capability::NegotiationMessage;
use tapestry_core::capability::{negotiate_hevc, Codec, CodecCapabilities};

#[test]
fn probed_h265_device_gets_h265() {
    let caps = CodecCapabilities::from_probe(vec![Codec::H264, Codec::H265]);
    assert_eq!(negotiate_hevc(&caps).unwrap(), Codec::H265);
}

#[test]
fn h265_capable_but_h265_only_after_probe_order_respected() {
    // Probed order does not matter: capability, not preference order.
    let caps = CodecCapabilities::from_probe(vec![Codec::H265, Codec::H264]);
    assert_eq!(negotiate_hevc(&caps).unwrap(), Codec::H265);
}

#[test]
fn h264_only_device_falls_back() {
    let caps = CodecCapabilities::from_probe(vec![Codec::H264]);
    assert_eq!(negotiate_hevc(&caps).unwrap(), Codec::H264);
}

#[test]
fn unprobed_device_refuses_hevc_content() {
    // Fire TV platform label must not imply codec support (directive §40).
    let caps = CodecCapabilities::unknown();
    assert!(negotiate_hevc(&caps).is_err());
    assert_eq!(caps.select_for_hevc_content(), None);
}

#[test]
fn negotiation_message_types_are_wire_stable() {
    let propose = NegotiationMessage::Propose {
        codecs: vec![Codec::H265, Codec::H264],
    };
    let json = serde_json::to_string(&propose).unwrap();
    assert!(json.contains("\"propose\""));
    let back: NegotiationMessage = serde_json::from_str(&json).unwrap();
    assert_eq!(propose, back);
}

#[test]
fn negotiate_returns_error_type_not_panic() {
    let caps = CodecCapabilities::from_probe(vec![]);
    let result = negotiate_hevc(&caps);
    let err = result.unwrap_err();
    assert!(err.to_string().contains("refusing to assume codec support"));
}

//! TAP frame encode → decode → encode byte stability, chunk resume
//! behaviour, and validation guards.

use tapestry_core::capability::NegotiationMessage;
use tapestry_core::ids::{ArtifactId, DeviceId, SessionId};
use tapestry_core::protocol::chunk::{ChunkAck, TransferState};
use tapestry_core::protocol::frame::{Frame, MAX_CHUNK_LEN, MAX_FRAME_PAYLOAD};
use tapestry_core::protocol::negotiate::Handshake;
use tapestry_core::protocol::Channel;
use tapestry_core::{TapestryError, TAP_VERSION};

fn chunk_frame(seq: u64, offset: u64, payload: Vec<u8>) -> Frame {
    let mut f = Frame::new(
        SessionId::generate(),
        Channel::Artefact,
        "chunk",
        seq,
        DeviceId::generate(),
        payload,
    );
    f.artifact = Some(ArtifactId::generate());
    f.offset = Some(offset);
    f
}

#[test]
fn encode_decode_encode_is_byte_identical() {
    let f = chunk_frame(441, 16_777_216, vec![0xABu8; 4096]);
    let first = f.to_json().unwrap();
    let decoded = Frame::from_json(&first).unwrap();
    let second = decoded.to_json().unwrap();
    assert_eq!(first, second);
}

#[test]
fn valid_chunks_validate() {
    let f = chunk_frame(1, 0, vec![0u8; 1024]);
    assert!(f.validate().is_ok());
}

#[test]
fn corrupted_payload_fails_validation() {
    let mut f = chunk_frame(1, 0, vec![1, 2, 3]);
    f.payload[0] ^= 0xff;
    match f.validate() {
        Err(TapestryError::InvalidValue {
            field: "digest", ..
        }) => {}
        other => panic!("expected digest error, got {other:?}"),
    }
}

#[test]
fn declared_length_must_match_payload() {
    let mut f = chunk_frame(1, 0, vec![1, 2, 3]);
    f.len = 999;
    assert!(f.validate().is_err());
}

#[test]
fn payload_over_max_frame_rejected() {
    let mut f = chunk_frame(1, 0, vec![0u8; 16]);
    f.len = MAX_FRAME_PAYLOAD + 1;
    assert!(f.validate().is_err());
}

#[test]
fn chunk_over_max_chunk_len_rejected() {
    let mut f = chunk_frame(1, 0, vec![0u8; 16]);
    f.len = MAX_CHUNK_LEN + 1;
    assert!(f.validate().is_err());
}

#[test]
fn full_transfer_resume_cycle() {
    let artifact = ArtifactId::generate();
    let payload = vec![7u8; (MAX_CHUNK_LEN * 3 + 512) as usize];
    let chunk_len = MAX_CHUNK_LEN;
    let mut state = TransferState::new(artifact.clone(), payload.len() as u64, chunk_len).unwrap();

    let mut seq = 0u64;
    let mut sent: Vec<Frame> = Vec::new();
    while let Some(offset) = state.next_offset() {
        let end = ((offset + chunk_len) as usize).min(payload.len());
        let slice = payload[offset as usize..end].to_vec();
        let frame = chunk_frame(seq, offset, slice);
        frame.validate().unwrap();
        state.acknowledge(offset, &frame.digest).unwrap();
        sent.push(frame);
        seq += 1;
    }
    assert!(state.is_complete());
    assert_eq!(sent.len(), 4);

    // Simulate reconnect: last two acks "lost", replay from resume point.
    let mut resumed = TransferState::new(artifact, payload.len() as u64, chunk_len).unwrap();
    for f in &sent[..2] {
        resumed.acknowledge(f.offset.unwrap(), &f.digest).unwrap();
    }
    assert_eq!(resumed.next_offset(), sent[2].offset);

    // Replaying an already-applied ack is a no-op.
    assert!(!resumed
        .acknowledge(sent[1].offset.unwrap(), &sent[1].digest)
        .unwrap());
}

#[test]
fn ack_payload_roundtrip() {
    let ack = ChunkAck {
        artifact: ArtifactId::generate(),
        offset: 1 << 20,
        digest: "aa".repeat(32),
    };
    let back: ChunkAck = serde_json::from_str(&serde_json::to_string(&ack).unwrap()).unwrap();
    assert_eq!(ack, back);
}

#[test]
fn handshake_and_negotiation_roundtrip() {
    let hs = Handshake::Hello {
        tap_version: tapestry_core::identity::TapVersion::new(1, 0),
    };
    let back: Handshake = serde_json::from_str(&serde_json::to_string(&hs).unwrap()).unwrap();
    assert_eq!(hs, back);

    let neg = NegotiationMessage::Propose {
        codecs: vec![tapestry_core::capability::Codec::H265],
    };
    let back: NegotiationMessage =
        serde_json::from_str(&serde_json::to_string(&neg).unwrap()).unwrap();
    assert_eq!(neg, back);
}

#[test]
fn protocol_constant_matches_tap1() {
    assert_eq!(TAP_VERSION, "TAP/1");
    assert_eq!(tapestry_core::protocol::PROTOCOL_VERSION, 1);
}

#[test]
fn unknown_field_in_frame_rejected() {
    let f = chunk_frame(1, 0, vec![1]);
    let mut json = serde_json::to_value(&f).unwrap();
    json["extraneous"] = serde_json::json!(1);
    let bytes = serde_json::to_vec(&json).unwrap();
    assert!(Frame::from_json(&bytes).is_err());
